"Glutwicht": "余烬小鬼",
"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "狗刚走，狐狸又在畜棚边转悠。把它们赶回草原",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "野猪吃光了农民的收成。没有存粮的冬天会要了我们的命",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "草原边缘燃着一块怒火之石，它的怒意让野兽发狂——砸碎它",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "幸好包派你来。强盗在林间小路上袭击每个商人，把他们赶走",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "这里的野猪长着荆刺而非鬃毛，它们撕碎我们的陷阱——连同猎人",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "森林深处的巨型蜘蛛在路上结网。必要时就烧了它们",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "森林中央长出一块荆棘之石，它的藤蔓扼死每一棵树。摧毁它",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "是哈根派你来的？那就来吧，兽人已经兵临栅栏。削弱他们的军队",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "兽人把鬣狗当狗养，放它们来扑咬我们的斥候。消灭这群畜生",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "是伊德里斯派你来的？诸神眷顾萨赫拉。眼镜蛇潜伏在每一处水源",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "听到那沙沙声了吗？响尾蛇，成百上千。商队都不敢出发了",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "有人在冰霜峰看到了房子那么大的雪人。带回它们的毛皮作为证据",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "自从严寒不退，猛犸就狂暴起来，践踏我们的储物棚",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "寂静之石所在之处，所有歌声都会沉寂。让声音重回山巅",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "最后也是最强大的灵魂石。摧毁它，灵魂石就不再生长",
"Hunde aus der Asche": "灰烬中的猎犬",
"Diebe im Zwielicht": "暮光中的盗贼",
"Wölfe aus dem Nebel": "雾中之狼",
"Die bleichen Geweihe": "苍白鹿角",
"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "长着发光鹿角的夜鹿冲撞我们的围栏，像是被什么追赶。拦住它们",
"Die Leitwölfe": "头狼",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "每支雾中狼群都跟随一头夜之头狼，没了它，狼群便会在雾中四散",
"Keiler im Mondkraut": "月草中的野猪",
"Glut im Aschewald": "灰烬之森的余火",
"Räuber in der Asche": "灰中劫匪",
"Glühende Hauer": "炽热獠牙",
"Die Keiler hier tragen Glut im Borstenkamm. Wo sie sich reiben, fängt das Unterholz Feuer": "这里的野猪鬃毛中带着余火，它们蹭过的地方灌木就会着火",
"Schützen im Rauch": "烟中射手",
"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "煤烟射手在被看见前就从烟雾中放箭。把他们从烧焦的树冠里揪出来",
"Graue Netze": "灰色蛛网",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "两块贪婪之石像余火招蛾般吸引劫匪。砸碎它们",
"Rußgraue Jäger": "煤灰色的猎手",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "煤烟猞猁在灰烬中隐形，我们的烧炭工再也没回来。你要比它们更警觉",
"Kohlenbären": "煤炭熊",
"Knochen im Sand": "沙中白骨",
"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "是阿斯坎派你来的？那就来吧，碎骨者已经到了我们的环城前。冲散他们的阵列",
"Aashyänen": "食腐鬣狗",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "鬣狗跟着碎骨者，吃它们留下的东西。消灭这群畜生",
"Die Knochenruferinnen": "唤骨者们",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "唤骨者用歌声把骸骨从沙中唤起。没有她们的歌声，死者就会长眠",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "两块黑石耸出沙丘，骸骨聚集在周围。夺走它们的核心",
"Bleiche Stachel": "苍白毒刺",
"Die Knochenhauptmänner": "骸骨队长们",
"Die Beinbrecher gehorchen Hauptmännern in alten Rüstungen. Fällst du sie, zerfällt das Heer": "碎骨者听命于身穿旧甲的队长。击倒他们，大军便会瓦解",
"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "一块灰烬之石从内部焚烧着沙漠。在只剩尘土之前熄灭它",
"Rot am Horizont": "地平线上的血红",
"Ossian hat recht, dich zu schicken. Blutoger stampfen jede Nacht gegen unsere Inseln. Halte sie fern": "奥西安派你来是对的。血食人魔每晚都冲击我们的岛屿，把它们挡在外面",
"Wargrudel der Steppe": "草原座狼群",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "草原座狼成群在红草中狩猎。在它们猎杀我们之前先猎杀它们",
"Blutdämonen": "血魔",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "血魔从红色水潭中升起，把它们赶回深渊",
