"Wolfsplage": "狼灾",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen": "狼群越来越大胆了。在它们到达城门前削减狼群",
"Verirrte Hirsche": "迷途的鹿",
"Der Alpha": "头狼",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel": "狼群背后是它们的首领——头狼。没有它们，狼群就会瓦解",
"Keiler in den Rüben": "萝卜地里的野猪",
"Auf in den Dunkelwald": "前往暗林",
"Banditen im Dunkelwald": "暗林中的强盗",
"Schützen im Dickicht": "灌木丛中的弓手",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter": "强盗在树冠上射击一切会动的东西。把他们打下来",
"Netz der Spinnen": "蜘蛛之网",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie": "两块贪婪之石吸引强盗，就像黄金吸引窃贼。砸碎它们",
"Lautlose Jäger": "无声猎手",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie": "猞猁在无人察觉时扑杀我们的斥候。要比它们更警觉",
"Der Banditenfürst": "强盗头子",
"Der Braunbär": "棕熊",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig": "一群棕熊占据了伐木小径。它们很强，小心",
"Krieg in der Rostschlucht": "锈峡之战",
"Orks vor der Talwacht": "谷哨前的兽人",
"Hyänen der Orks": "兽人的鬣狗",
"Die Schamanen": "萨满们",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut": "他们的萨满诅咒山谷。没有萨满，兽人就会丧失勇气",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen": "兽人崇拜黑石。夺走他们的偶像",
"Stachel im Sand": "沙中之刺",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten": "巨蝎在石缝里筑巢，毒液能麻痹一头牛。清理石缝",
"Der Ork-Hauptmann": "兽人队长",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie": "没有队长，兽人只是一群乌合之众。找到他们",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt": "灰烬之石从内部焚烧山谷。在只剩尘土前熄灭它",
"Asche über dem Ödland": "荒原上的灰烬",
"Oger im Aschenfeld": "灰烬原野的食人魔",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern": "斯拉克派你来是对的。食人魔每晚都来洗劫营地。把它们挡在外面",
"Wargrudel": "座狼群",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel": "座狼跟着食人魔吃剩下的东西。猎杀狼群",
"Dämonen im Ödland": "荒原上的恶魔",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe": "恶魔从荒原的裂缝中升起。把它们赶回深处",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus": "余烬之石让荒原燃烧。熄灭它们",
"Höllenhunde": "地狱犬",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen": "三头犬守护着裂缝。击败它们才能接近裂缝",
"Die Oase im Süden": "南方的绿洲",
"Kobras in der Wüste": "沙漠中的眼镜蛇",
"Das Rasseln im Sand": "沙中的响声",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder": "丛林里的蟒蛇能绞死整头牛。在那里伐木的人再也回不来",
"Schwarze Panther": "黑豹",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher": "娜迦的黑豹在夜间狩猎。让丛林重归安全",
"Eis im Norden": "北方之冰",
"Eiswölfe": "冰狼",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche": "哈基姆派你来的？很好。冰狼在营地周围徘徊，嗅得出每一丝弱点",
"Der Yeti": "雪人",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie": "两块冰霜之石让山顶永不消融。砸碎它们",
"Wilde Mammuts": "野生猛犸",
"Frostgeister": "冰霜之灵",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen": "幽灵在暴风雪中游荡。碰到它们的人会从内而外冻僵",
"Der Eiskönig": "冰王",
"Nebel über dem Moor": "沼泽上的迷雾",
"Das Totenmoor": "死亡沼泽",
"Moorwölfe": "沼泽狼",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest": "这里的狼半死不活，却仍不停狩猎。了结它们",
"Die Sumpfhexen": "沼泽女巫",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu": "女巫从泥沼中召唤亡者。没有她们，坟墓就会保持封闭",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr": "两块腐朽之石污染了水源。再也长不出任何活物",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller": "食尸鬼吞食女巫唤醒的东西。它们又快又饿。要比它们更快",
"Donner in der Klamm": "峡谷中的雷鸣",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke": "是奥斯温派你来的？巨魔正围攻峡谷。让它们见识我们的力量",
"Harpyien": "鹰身女妖",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft": "鹰身女妖会俯冲攻击每个登上山口的人。把它们从空中打下来",
"Die Minotauren": "牛头怪们",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf": "牛头怪低着角冲撞我们的大门。阻止它们",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz": "血红的石头从岩石中长出，以痛苦为食",
"Erwachte Titanen": "觉醒的泰坦",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer": "石泰坦在泰坦山脊上站起。让它们重新静止——永远",
"Der Berg brennt": "火山燃烧",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu": "贡希尔德派你来的？那你已经准备好了。熔岩魔像正朝我们的营地涌来",
"Glutkatzen": "余烬猫",
"Glutkatzen streifen durch die Lavafelder. Wo sie laufen, brennt der Boden": "余烬猫在熔岩地游荡，所到之处地面燃烧",
"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse": "两块火焰之石加热了火山。没有它们，熔岩河就会熄灭",
"Feuerdämonen": "火焰恶魔",
"Aus den Kratern steigen Feuerdämonen. Treib sie zurück ins Feuer": "火焰恶魔从火山口升起。把它们赶回火中",
"Feuerdrachen": "火龙",
"Am Feuerberg nisten Drachen. Wenn sie flügge werden, ist kein Dorf mehr sicher": "火山上筑有龙巢。等它们羽翼丰满，就没有村庄是安全的",
"Heimkehr nach Kazehana": "重返风花",
"Finale": "终章",
"Die neun Endbosse": "九大最终首领",
"Prüfung des Stallmeisters": "马厩总管的考验",
"Halt die Augen offen. Hinter den Wiesen beginnt der Dunkelwald, und dort lauern Banditen": "保持警惕。草地后面就是暗林，强盗潜伏在那里",
"Seit die Seelensteine aus der Erde brechen, wächst kaum noch etwas auf den Feldern": "自从灵魂石破土而出，田里几乎什么都长不出来",
"Wenn ich groß bin, werde ich auch Abenteurer": "等我长大了，我也要当冒险者",
"Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine": "风花曾是个宁静的小城。后来石头来了",
